const L = (...lines) => lines.flat().join("\n") + "\n";

export function preCommit() {
  return L(
    "# Generated by vibe-it-securely.",
    "# FAST local checks. CI re-runs them, because hooks can be bypassed (git commit --no-verify).",
    "# Install once:  pip install pre-commit && pre-commit install",
    "repos:",
    "  - repo: https://github.com/pre-commit/pre-commit-hooks",
    "    rev: v4.6.0",
    "    hooks:",
    "      - id: detect-private-key",
    "      - id: check-added-large-files",
    "  - repo: https://github.com/gitleaks/gitleaks",
    "    rev: v8.18.4",
    "    hooks:",
    "      - id: gitleaks",
  );
}

export function ciWorkflow(projects) {
  const steps = [
    "      - uses: actions/checkout@v4",
    "        with:",
    "          fetch-depth: 0",
    "      - uses: actions/setup-python@v5",
    "        with:",
    "          python-version: \"3.12\"",
    "",
    "      # False alarm on a fake value? Add the finding Fingerprint to .gitleaksignore",
    "      - name: Secret scan (blocking)",
    "        run: |",
    "          curl -sSL https://github.com/gitleaks/gitleaks/releases/download/v8.18.4/gitleaks_8.18.4_linux_x64.tar.gz | tar -xz gitleaks",
    "          ./gitleaks detect --source . --redact --verbose",
    "      - name: Hygiene hooks (blocking)",
    "        run: |",
    "          pip install pre-commit",
    "          SKIP=gitleaks pre-commit run --all-files",
  ];

  const nodeProjects = projects.filter((p) => p.stack.node);
  const pyProjects = projects.filter((p) => p.stack.python);
  const wd = (p) => (p.path ? ["        working-directory: " + p.path] : []);
  const label = (p) => (p.path ? " (" + p.path + ")" : "");

  if (nodeProjects.length) {
    steps.push("", "      - uses: actions/setup-node@v4", "        with:", "          node-version: \"22\"");
  }
  for (const p of nodeProjects) {
    const s = p.stack;
    const head = ["      - name: Dependency audit" + label(p) + ", critical only (blocking)", ...wd(p)];
    if (s.packageManager === "pnpm") {
      steps.push(...head, "        run: |", "          corepack enable", "          pnpm audit --audit-level critical");
    } else if (s.packageManager === "yarn") {
      steps.push(...head, "        # TODO: Yarn Berry uses \"yarn npm audit\" instead.", "        run: yarn audit --level critical");
    } else {
      steps.push(...head, "        run: |");
      if (!s.hasNodeLock) steps.push("          npm install --package-lock-only --ignore-scripts");
      steps.push("          npm audit --audit-level=critical");
    }
  }

  for (const p of pyProjects) {
    const s = p.stack;
    const target = s.pythonDeps === "requirements.txt" ? "-r requirements.txt" : s.pythonDeps === "pipfile" ? "" : ".";
    steps.push(
      "",
      "      - name: Python dependency audit" + label(p) + " (warning only: pip-audit cannot filter by severity)",
      ...wd(p),
      "        continue-on-error: true",
      "        run: |",
      "          pip install pip-audit",
      target
        ? "          pip-audit " + target
        : "          # TODO: Pipfile detected. Run: pipenv requirements | pip-audit -r /dev/stdin",
    );
  }

  steps.push(
    "",
    "      - name: Static analysis, errors only (blocking)",
    "        run: |",
    "          pip install semgrep",
    "          semgrep scan --config p/default --severity ERROR --error",
    "      - name: Static analysis, warnings (report only)",
    "        continue-on-error: true",
    "        run: semgrep scan --config p/default --severity WARNING",
  );

  return L(
    "# Generated by vibe-it-securely. This is a security BASELINE, not a guarantee of security.",
    "# TODO: pin third-party actions to commit SHAs for stronger supply-chain safety.",
    "name: Security baseline",
    "on:",
    "  push:",
    "    branches: [main]",
    "  pull_request:",
    "permissions:",
    "  contents: read",
    "jobs:",
    "  baseline:",
    "    runs-on: ubuntu-latest",
    "    steps:",
    steps,
  );
}

export function dockerfileNode(stack) {
  const pm = stack.packageManager || "npm";
  const copy = pm === "pnpm" ? "package.json pnpm-lock.yaml*" : pm === "yarn" ? "package.json yarn.lock*" : "package*.json";
  const install =
    pm === "pnpm"
      ? "corepack enable && pnpm install --frozen-lockfile"
      : pm === "yarn"
        ? "corepack enable && yarn install --frozen-lockfile"
        : stack.hasNodeLock
          ? "npm ci"
          : "npm install";
  const prune = pm === "pnpm" ? "pnpm prune --prod" : pm === "npm" ? "npm prune --omit=dev" : null;

  return L(
    "# syntax=docker/dockerfile:1",
    "# Generated by vibe-it-securely. TODO: pin base images by digest (node:22-slim@sha256:...).",
    "FROM node:22-slim AS build",
    "WORKDIR /app",
    "COPY " + copy + " ./",
    "RUN " + install,
    "COPY . .",
    "# TODO: if your project has a build step (TypeScript, bundlers), enable:",
    "# RUN npm run build",
    prune ? "RUN " + prune : "# TODO: remove dev dependencies for this package manager",
    "",
    "FROM node:22-slim",
    "ENV NODE_ENV=production",
    "WORKDIR /app",
    "# Run as the unprivileged node user, never as root",
    "COPY --from=build --chown=node:node /app /app",
    "USER node",
    "EXPOSE 3000",
    "# TODO: confirm npm start runs your app",
    "CMD [\"npm\", \"start\"]",
  );
}

export function dockerfilePython(stack) {
  const reqs = stack.pythonDeps === "requirements.txt";
  return L(
    "# syntax=docker/dockerfile:1",
    "# Generated by vibe-it-securely. TODO: pin base images by digest (python:3.12-slim@sha256:...).",
    "FROM python:3.12-slim AS build",
    "WORKDIR /app",
    "ENV PIP_NO_CACHE_DIR=1",
    "RUN python -m venv /opt/venv",
    "ENV PATH=\"/opt/venv/bin:$PATH\"",
    reqs
      ? ["COPY requirements.txt ./", "RUN pip install -r requirements.txt"]
      : ["COPY . .", "RUN pip install ."],
    "",
    "FROM python:3.12-slim",
    "ENV PYTHONDONTWRITEBYTECODE=1 PYTHONUNBUFFERED=1 PATH=\"/opt/venv/bin:$PATH\"",
    "# Run as an unprivileged user, never as root",
    "RUN useradd --create-home --uid 10001 app",
    "WORKDIR /app",
    "COPY --from=build /opt/venv /opt/venv",
    "COPY --chown=app:app . .",
    "USER app",
    "EXPOSE 8000",
    "# TODO: replace with your real start command",
    "CMD [\"python\", \"main.py\"]",
  );
}

export function dockerignore() {
  return L(".git", ".env", ".env.*", "!.env.example", "*.pem", "*.key", "node_modules", "__pycache__", ".venv", ".github", "Dockerfile*");
}

export function envExample() {
  return L(
    "# Copy to .env and fill in real values. NEVER commit .env.",
    "# Keep placeholders here, never real secrets.",
    "DATABASE_URL=",
    "API_KEY=",
    "SECRET_KEY=",
  );
}

export function gitleaksIgnore() {
  return L(
    "# Generated by vibe-it-securely.",
    "# Secret-scan false alarm? Copy the Fingerprint line from the CI log into this file, one per line.",
    "# Only do this for fake or example values. For a real secret: revoke it and replace it.",
  );
}

export function gitignore() {
  return L(".env", ".env.*", "!.env.example", "node_modules/", "__pycache__/", ".venv/", "*.pem", "*.key");
}

export function agentRules(stack) {
  const rules = [
    "# Security rules for AI coding assistants",
    "",
    "Generated by vibe-it-securely. Follow these in all code you write or modify.",
    "",
    "## Always",
    "- Never hardcode secrets, tokens, passwords or API keys. Read them from environment variables and add new ones to `.env.example` with empty values.",
    "- Validate and sanitize all external input (request bodies, query params, files, env vars).",
    "- Use parameterized queries or an ORM. Never build SQL by string concatenation.",
    "- Add authentication AND authorization checks to every endpoint that touches user data.",
    "- Keep CORS restrictive: list allowed origins explicitly, never `*` with credentials.",
    "- Do not log secrets, tokens or personal data.",
    "- Prefer well-maintained libraries; do not add a dependency for something trivial.",
    "- Run containers as a non-root user.",
    "",
    "## Never",
    "- Never disable TLS verification or security linters to make an error go away.",
    "- Never commit `.env`, private keys or credentials.",
    "- Never use `--no-verify` to skip the pre-commit hooks.",
  ];
  if (stack.node) {
    rules.push(
      "",
      "## JavaScript / TypeScript",
      "- Never use `eval`, `new Function`, or `child_process.exec` with user input.",
      "- Validate request data with a schema library (e.g. zod) at the API boundary.",
      "- Never render user input with `dangerouslySetInnerHTML` or `innerHTML` unsanitized.",
    );
  }
  if (stack.python) {
    rules.push(
      "",
      "## Python",
      "- Never use `eval`, `exec`, `pickle.loads` on untrusted data, or `subprocess` with `shell=True` and user input.",
      "- Use `yaml.safe_load`, never `yaml.load`.",
      "- Use `secrets` (not `random`) for tokens and anything security-related.",
    );
  }
  rules.push("", "If a task seems to require breaking a rule above, stop and ask the user first.");
  return L(rules);
}
